public async Task<string> LoadSessionAsync(string sessionId, CancellationToken cancellationToken)
{
    var redisTask = _redis.GetDatabase().StringGetAsync(sessionId);
    var introspectTask = _http.GetStringAsync($"/oauth/introspect/{sessionId}", cancellationToken);
    await Task.WhenAll(redisTask, introspectTask);
    return redisTask.Result.ToString() ?? introspectTask.Result;
}
